#!/usr/bin/env python3
"""Ajoute le logo BetPawa dans match_template.html (a lancer a la racine du projet)."""
import sys
p = sys.argv[1] if len(sys.argv) > 1 else "match_template.html"
s = open(p, encoding="utf-8").read()
if '"betpawa": "data:image' in s:
    print("Logo deja present."); raise SystemExit
LINE = '    "betpawa": "data:image/jpeg;base64,",\n'
if "const LOGOS = {\n" not in s:
    raise SystemExit("Bloc LOGOS introuvable")
s = s.replace("const LOGOS = {\n", "const LOGOS = {\n" + LINE, 1)
open(p, "w", encoding="utf-8").write(s)
print("Logo BetPawa ajoute dans", p)

